create table MB_PROD_DEFINE (PROD_TYPE VARCHAR(20) not null  ,SEQ_NO VARCHAR(50) not null  ,ASSEMBLE_TYPE VARCHAR(10) null  ,ASSEMBLE_ID VARCHAR(50) null  ,ATTR_KEY VARCHAR(30) null  ,ATTR_VALUE VARCHAR(50) null  ,EVENT_DEFAULT VARCHAR(10) null  ,STATUS VARCHAR(1) null  ,COMPANY VARCHAR(20) not null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(PROD_TYPE,SEQ_NO,COMPANY));